// TailSend Web telemetry — Firebase web app config.
// Replace each "PLACEHOLDER" with the values from the Firebase console
// (Project settings > Your apps > Web app > SDK setup and configuration).
//
// While placeholders remain, Firebase is never initialized and all
// telemetry calls are silent no-ops (see telemetry.js).
//
// Note: the apiKey below is a client-side public identifier (not a secret),
// so the app already works with a real key committed here. It is kept as a
// placeholder only so telemetry stays off until the project is set up.
window.__FIREBASE_CONFIG__ = {
    apiKey: "PLACEHOLDER",
    authDomain: "PLACEHOLDER.firebaseapp.com",
    projectId: "PLACEHOLDER",
    storageBucket: "PLACEHOLDER.appspot.com",
    messagingSenderId: "PLACEHOLDER",
    appId: "PLACEHOLDER",
    measurementId: "G-PLACEHOLDER"
};
